tmp=setup("/tmp/cliR", files)
r=run(tmp,["-recursive","."])
for n in names: print(n, ch(tmp+"/"+n+"/x.go"))
# maybe top-level files vs dir .git is hidden from filepath.Walk due to ??? Also check hidden files a/.hidden?
