)

func trimPath(s string) string { return strings.Trim(s, "\"") }
func main(){
 data, _ := os.ReadFile(os.Args[1])
 fset := token.NewFileSet()
 f, err := parser.ParseFile(fset, os.Args[1], data, parser.ParseComments)
 if err!=nil{ panic(err)}
 // collect
 type imp struct{spec *ast.ImportSpec; path, alias string}
 var imps []*imp
 var firstDecl *ast.GenDecl
 var newDecls []ast.Decl
 var declMap = map[ast.Decl]bool{}
 for _, d := range f.Decls {
   gd, ok := d.(*ast.GenDecl); if !ok || gd.Tok!=token.IMPORT { continue }
   if len(gd.Specs)==1 {
      if sp, ok:=gd.Specs[0].(*ast.ImportSpec); ok && trimPath(sp.Path.Value)=="C" { continue }
   }
   if firstDecl==nil { firstDecl=gd }
   declMap[gd]=true
   for _, s := range gd.Specs {
     sp:=s.(*ast.ImportSpec)
     alias:=""; if sp.Name!=nil { alias=sp.Name.Name }
     imps=append(imps, &imp{sp, trimPath(sp.Path.Value), alias})
   }
 }
 // dedup map overwrite
 m:=map[string]*imp{}
 for _,im:=range imps { m[im.alias+"|"+im.path]=im }
 var uniq []*imp; for _,v:=range m{uniq=append(uniq,v)}
 sort.Slice(uniq, func(i,j int)bool{ if uniq[i].path!=uniq[j].path { return uniq[i].path<uniq[j].path}; return uniq[i].alias<uniq[j].alias})
 // build specs fresh
 var specs []ast.Spec
 for _,im:=range uniq {
   ns:=&ast.ImportSpec{Path:&ast.BasicLit{Kind:token.STRING, Value: strconv.Quote(im.path)}, Comment: im.spec.Comment}
   if im.alias!="" { ns.Name=ast.NewIdent(im.alias)}
   // clear original comment? keep ref
   specs=append(specs, ns)
   _ = im
 }
 newDecl:=&ast.GenDecl{TokPos: firstDecl.TokPos, Tok: token.IMPORT, Specs: specs, Doc: firstDecl.Doc}
 if len(specs)!=1 || firstDecl.Lparen.IsValid() { newDecl.Lparen = firstDecl.TokPos+token.Pos(len("import")) }
 // rebuild decls
 var outDecls []ast.Decl
 inserted:=false
 for _,d:=range f.Decls {
   if declMap[d] {
      if !inserted { outDecls=append(outDecls,newDecl); inserted=true }
      continue
   }
   outDecls=append(outDecls,d)
 }
 f.Decls=outDecls
 var buf bytes.Buffer
 err=format.Node(&buf, fset, f)
 if err!=nil{ panic(err)}
 fmt.Print(buf.String())
}
