// ---------- groups / order ----------

type groupType int

const (
	groupStd groupType = iota
	groupGeneral
	groupCompany
	groupProject
	groupBlanked
	groupDotted
)

func parseImportsOrderOption(s string) ([]groupType, error) {
	def := []groupType{groupStd, groupGeneral, groupCompany, groupProject}
	if s == "" {
		return def, nil
	}
	parts := strings.Split(s, ",")
	result := make([]groupType, 0, len(parts))
	seen := make(map[groupType]bool)
	for _, part := range parts {
		p := strings.TrimSpace(part)
		var g groupType
		switch p {
		case "std":
			g = groupStd
		case "general":
			g = groupGeneral
		case "company":
			g = groupCompany
		case "project":
			g = groupProject
		case "blanked":
			g = groupBlanked
		case "dotted":
			g = groupDotted
		default:
			return nil, fmt.Errorf("unknown order group type: %q", p)
		}
		result = append(result, g)
		seen[g] = true
	}
	if len(result) < 4 || !seen[groupStd] || !seen[groupGeneral] || !seen[groupCompany] || !seen[groupProject] {
		return nil, errors.New("use default at least 4 parameters to sort groups of your imports: \"std,general,company,project\"")
	}
	return result, nil
}

type options struct {
	projectName             string
	companyPrefixes         []string
	excludes                []string
	importsOrder            []groupType
	importsOrderSet         map[groupType]bool
	rmUnused                bool
	setAlias                bool
	separateNamed           bool
	withFormat              bool
	applyToGeneratedFiles   bool
	useCache                bool
}

// ---------- project name ----------

func determineProjectName(path string) (string, error) {
	startDir := ""
	if info, err := os.Stat(path); err == nil && info.IsDir() {
		startDir = path
	} else {
		startDir = filepath.Dir(path)
	}
	dir := startDir
	for {
		candidate := filepath.Join(dir, "go.mod")
		modName, exists, err := parseGoMod(candidate)
		if err == nil {
			return modName, nil
		}
		if exists {
			return "", err
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			if dir == "." || dir == "" {
				return "", err
			}
			// Final fallback: go.mod in the current directory.
			modName, _, err2 := parseGoMod("go.mod")
			if err2 != nil {
				return "", err2
			}
			return modName, nil
		}
		dir = parent
	}
}

// parseGoMod parses a go.mod file (subset compatible with go.mod syntax).
// exists reports whether the file was present (so parse errors should be
// reported rather than continuing the search in a parent directory).
func parseGoMod(filename string) (string, bool, error) {
	data, err := os.ReadFile(filename)
	if err != nil {
		if os.IsNotExist(err) {
			return "", false, err
		}
		return "", true, err
	}
	modulePath := ""
	seenModule := false
	inBlockVerb := ""
	lines := strings.Split(string(data), "\n")
	for idx, rawLine := range lines {
		lineNo := idx + 1
		line := strings.TrimSpace(stripModComment(rawLine))
		if inBlockVerb != "" {
			if line == ")" {
				inBlockVerb = ""
				continue
			}
			if inBlockVerb == "module" {
				if line == "" {
					continue
				}
				fields := splitModFields(line)
				if len(fields) > 0 && modulePath == "" {
					p, err := unquoteModValue(fields[0])
					if err != nil {
						return "", true, fmt.Errorf("%s:%d: %s", filename, lineNo, err.Error())
					}
					modulePath = p
				}
			}
			continue
		}
		if line == "" {
			continue
		}
		fields := splitModFields(line)
		if len(fields) == 0 {
			continue
		}
		verb := fields[0]
		switch verb {
		case "module", "go", "toolchain", "godebug", "require", "exclude", "replace", "retract":
		default:
			return "", true, fmt.Errorf("%s:%d: unknown directive: %s", filename, lineNo, verb)
		}
		if len(fields) > 1 && fields[1] == "(" {
			inBlockVerb = verb
			if verb == "module" {
				if seenModule {
					return "", true, fmt.Errorf("%s:%d: repeated module statement", filename, lineNo)
				}
				seenModule = true
			}
			continue
		}
		if verb == "module" {
			if seenModule {
				return "", true, fmt.Errorf("%s:%d: repeated module statement", filename, lineNo)
			}
			seenModule = true
			if len(fields) < 2 {
				return "", true, fmt.Errorf("%s:%d: module statement missing path", filename, lineNo)
			}
			p, err := unquoteModValue(fields[1])
			if err != nil {
				return "", true, fmt.Errorf("%s:%d: %s", filename, lineNo, err.Error())
			}
			modulePath = p
		}
	}
	if modulePath == "" {
		return "", true, errors.New("module is undefined")
	}
	return modulePath, true, nil
}

func stripModComment(line string) string {
	inQuote := false
	inRaw := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		if inRaw {
			if c == '`' {
				inRaw = false
			}
			continue
		}
		if inQuote {
			if c == '\\' {
				i++
				continue
			}
			if c == '"' {
				inQuote = false
			}
			continue
		}
		switch c {
		case '`':
			inRaw = true
		case '"':
			inQuote = true
		case '/':
			if i+1 < len(line) && line[i+1] == '/' {
				return line[:i]
			}
		}
	}
	return line
}

func splitModFields(line string) []string {
	var fields []string
	i := 0
	for i < len(line) {
		for i < len(line) && (line[i] == ' ' || line[i] == '\t' || line[i] == '\r') {
			i++
		}
		if i >= len(line) {
			break
		}
		start := i
		if line[i] == '"' {
			i++
			for i < len(line) {
				if line[i] == '\\' {
					i += 2
					continue
				}
				if line[i] == '"' {
					i++
					break
				}
				i++
			}
		} else if line[i] == '`' {
			i++
			for i < len(line) && line[i] != '`' {
				i++
			}
			if i < len(line) {
				i++
			}
		} else {
			for i < len(line) && line[i] != ' ' && line[i] != '\t' && line[i] != '\r' {
				i++
			}
		}
		fields = append(fields, line[start:i])
	}
	return fields
}

func unquoteModValue(s string) (string, error) {
	if len(s) >= 2 && (s[0] == '"' || s[0] == '`') {
		v, err := strconv.Unquote(s)
		if err != nil {
			return "", err
		}
		return v, nil
	}
	return s, nil
}

// ---------- stdin / file / directory processing ----------

func processStdin(opts *options) {
	content, err := io.ReadAll(os.Stdin)
	if err != nil {
		log.Fatalf("Failed to fix file: %s", err.Error())
	}
	if opts.useCache {
		ensureCacheDir()
	}
	fixed, changed, err := fixContent("<standard-input>", content, opts, ".")
	if err != nil {
		log.Fatalf("Failed to fix file: %s", err.Error())
	}
	if opts.useCache {
		writeCacheFor("<standard-input>", fixed)
	}
	if setExitStatus && changed {
		exitWithStatus = true
	}
	if listDiff && changed {
		fmt.Println("<standard-input>")
	} else {
		fmt.Print(string(fixed))
	}
}

func processSingleFile(path string, opts *options) {
	absPath, err := filepath.Abs(path)
	if err != nil {
		absPath = path
	}
	fixed, changed, cacheHit, err := fixFile(absPath, opts)
	if err != nil {
		log.Fatalf("Failed to fix file: %s", err.Error())
	}
	if cacheHit {
		return
	}
	if setExitStatus && changed {
		exitWithStatus = true
	}
	if outputStr == "stdout" {
		if listDiff && changed {
			fmt.Println(absPath)
		} else {
			fmt.Print(string(fixed))
		}
		return
	}
	if listDiff {
		fmt.Println(absPath)
		if outputStr != "write" {
			return
		}
	}
	if outputStr == "file" || outputStr == "write" {
		writeFixedResult(absPath, fixed)
		return
	}
	log.Fatalf("invalid output %q specified", outputStr)
}

func processDirectory(argPath, walkRoot string, recursive bool, opts *options) error {
	err := filepath.Walk(walkRoot, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return nil
		}
		if info.IsDir() {
			if path != walkRoot {
				rel, relErr := filepath.Rel(walkRoot, path)
				if relErr == nil {
					if !recursive {
						return filepath.SkipDir
					}
					// Skip well-known service directories directly below the root.
					if !strings.Contains(rel, string(os.PathSeparator)) {
						if info.Name() == ".git" || info.Name() == ".idea" || info.Name() == ".vscode" {
							return filepath.SkipDir
						}
					}
					if isExcluded(opts.excludes, walkRoot, path) {
						return filepath.SkipDir
					}
				}
			}
			return nil
		}
		if !strings.HasSuffix(info.Name(), ".go") {
			return nil
		}
		if isExcluded(opts.excludes, walkRoot, path) {
			return nil
		}
		absPath, err := filepath.Abs(path)
		if err != nil {
			absPath = path
		}
		fixed, changed, cacheHit, err := fixFile(absPath, opts)
		if err != nil {
			return fmt.Errorf("failed to fix %s: %w", absPath, err)
		}
		if cacheHit {
			return nil
		}
		if listDiff {
			if changed {
				fmt.Println(absPath)
			}
			return nil
		}
		if changed {
			writeFixedResult(absPath, fixed)
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to walk dif: %w", err)
	}
	return nil
}

func isExcluded(patterns []string, root, path string) bool {
	if len(patterns) == 0 {
		return false
	}
	rel, err := filepath.Rel(root, path)
	if err != nil {
		rel = path
	}
	absPath, err := filepath.Abs(path)
	if err != nil {
		absPath = path
	}
	for _, pattern := range patterns {
		if pattern == "" {
			continue
		}
		pat := filepath.Clean(pattern)
		if filepath.IsAbs(pat) {
			if ok, _ := filepath.Match(pat, absPath); ok {
				return true
			}
		} else {
			if ok, _ := filepath.Match(pat, rel); ok {
				return true
			}
			// Also allow matching against the path as walked (for patterns
			// given relative to the current directory when root differs).
			// This is deliberately secondary to the relative match above.
			if pat != rel {
				if ok, _ := filepath.Match(pat, absPath); ok {
					// Only absolute-ish patterns reach here; ignore.
					_ = ok
				}
			}
		}
	}
	return false
}

func writeFixedResult(absPath string, content []byte) {
	perm := os.FileMode(0644)
	if info, err := os.Stat(absPath); err == nil {
		perm = info.Mode().Perm()
	}
	if err := os.WriteFile(absPath, content, perm); err != nil {
		log.Fatalf("failed to write fixed result to file(%s): %s", absPath, err.Error())
	}
}

// ---------- cache ----------

func cacheDirPath() (string, bool) {
	base, err := os.UserCacheDir()
	if err != nil || base == "" {
		return "", false
	}
	return filepath.Join(base, "goimports-reviser"), true
}

func ensureCacheDir() (string, bool) {
	dir, ok := cacheDirPath()
	if !ok {
		return "", false
	}
	_ = os.MkdirAll(dir, 0755)
	return dir, true
}

func md5Hex(b []byte) string {
	sum := md5.Sum(b)
	return hex.EncodeToString(sum[:])
}

func md5HexStr(s string) string {
	return md5Hex([]byte(s))
}

func writeCacheFor(key string, content []byte) {
	dir, ok := ensureCacheDir()
	if !ok {
		return
	}
	name := md5HexStr(key)
	_ = os.WriteFile(filepath.Join(dir, name), []byte(md5Hex(content)), 0644)
}

// fixFile reads, fixes (and handles the cache for) a single on-disk file.
// The returned cacheHit indicates the file was already in the cached state.
func fixFile(absPath string, opts *options) ([]byte, bool, bool, error) {
	var cacheFile string
	if opts.useCache {
		if dir, ok := ensureCacheDir(); ok {
			cacheFile = filepath.Join(dir, md5HexStr(absPath))
		}
	}
	content, err := os.ReadFile(absPath)
	if err != nil {
		return nil, false, false, err
	}
	if opts.useCache && cacheFile != "" {
		if cached, err := os.ReadFile(cacheFile); err == nil {
			if string(cached) == md5Hex(content) {
				return nil, false, true, nil
			}
		}
	}
	fixed, changed, err := fixContent(absPath, content, opts, filepath.Dir(absPath))
	if err != nil {
		return nil, false, false, err
	}
	if opts.useCache && cacheFile != "" {
		_ = os.WriteFile(cacheFile, []byte(md5Hex(fixed)), 0644)
	}
	return fixed, changed, false, nil
}

// ---------- core fixing ----------

var generatedRe = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)

func fixContent(displayName string, content []byte, opts *options, loaderDir string) ([]byte, bool, error) {
	if len(content) == 0 {
		// Parse to obtain the parser's error message.
		fset0 := token.NewFileSet()
		_, perr := parser.ParseFile(fset0, displayName, content, parser.ParseComments)
		if perr == nil {
			perr = errors.New(displayName + ":1:1: expected 'package', found 'EOF'")
		}
		return nil, false, fmt.Errorf("file is empty and cannot be parsed as Go source, use -excludes flag to skip this file: %w", perr)
	}
	fset := token.NewFileSet()
	parsedFile, err := parser.ParseFile(fset, displayName, content, parser.ParseComments)
	if err != nil {
		return nil, false, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %w", err)
	}

	if !opts.applyToGeneratedFiles && isGeneratedFile(parsedFile) {
		return content, false, nil
	}

	// Collect import declarations.
	type declInfo struct {
		gd       *ast.GenDecl
		singleC  bool
		collected bool
	}
	var decls []*declInfo
	var firstCollected *ast.GenDecl
	var collectedInfos []*importInfo
	totalImportSpecs := 0
	for _, decl := range parsedFile.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		di := &declInfo{gd: gd}
		decls = append(decls, di)
		isSingleC := false
		if len(gd.Specs) == 1 {
			if sp, ok := gd.Specs[0].(*ast.ImportSpec); ok {
				if strings.Trim(sp.Path.Value, "\"") == "C" {
					isSingleC = true
				}
			}
		}
		di.singleC = isSingleC
		totalImportSpecs += len(gd.Specs)
		if isSingleC {
			continue
		}
		di.collected = true
		if firstCollected == nil {
			firstCollected = gd
		}
		for _, specNode := range gd.Specs {
			sp, ok := specNode.(*ast.ImportSpec)
			if !ok {
				continue
			}
			collectedInfos = append(collectedInfos, makeImportInfo(sp))
		}
	}

	// Deduplicate (later occurrences win).
	collectedInfos = dedupImports(collectedInfos)

	infos := collectedInfos
	if opts.rmUnused || opts.setAlias {
		if !(totalImportSpecs == 1 && len(parsedFile.Imports) == 1 && strings.Trim(parsedFile.Imports[0].Path.Value, "\"") == "C") {
			names, used, err := loadPackageInfo(loaderDir, displayName, fset, parsedFile)
			if err != nil {
				return nil, false, err
			}
			if opts.rmUnused {
				var kept []*importInfo
				for _, inf := range infos {
					if inf.alias == "_" || inf.alias == "." {
						kept = append(kept, inf)
						continue
					}
					if inf.path == "C" {
						kept = append(kept, inf)
						continue
					}
					if used[inf.path] {
						kept = append(kept, inf)
					}
				}
				infos = kept
			}
			if opts.setAlias {
				for _, inf := range infos {
					if inf.hasAlias {
						continue
					}
					loadedName, ok := names[inf.path]
					if !ok || loadedName == "" {
						continue
					}
					base := inf.path
					if idx := strings.LastIndex(base, "/"); idx >= 0 {
						base = base[idx+1:]
					}
					if loadedName != base {
						inf.alias = loadedName
						inf.hasAlias = true
					}
				}
			}
		}
	}

	var newContent []byte
	if firstCollected == nil {
		newContent = content
	} else {
		groups := buildGroups(infos, opts)
		totalRendered := 0
		for _, g := range groups {
			totalRendered += len(g)
		}
		var block string
		singleForm := false
		if totalRendered == 1 && firstCollected.Lparen == token.NoPos {
			singleForm = true
		}
		if totalRendered == 0 {
			block = ""
		} else if singleForm {
			var only *importInfo
			for _, g := range groups {
				if len(g) > 0 {
					only = g[0]
					break
				}
			}
			dupComment := len(decls) > 0 && countCollectedDecls(declsCountHelper(firstCollected, parsedFile)) == 1
			// Determine whether there is exactly one collected declaration:
			collectedDeclCount := 0
			for _, decl := range parsedFile.Decls {
				gd, ok := decl.(*ast.GenDecl)
				if !ok || gd.Tok != token.IMPORT {
					continue
				}
				if len(gd.Specs) == 1 {
					if sp, ok := gd.Specs[0].(*ast.ImportSpec); ok && strings.Trim(sp.Path.Value, "\"") == "C" {
						continue
					}
				}
				collectedDeclCount++
			}
			dupComment = collectedDeclCount == 1
			block = "import " + specLine(only, dupComment)
		} else {
			var sb strings.Builder
			sb.WriteString("import (\n")
			for gi, g := range groups {
				if gi > 0 {
					sb.WriteString("\n")
				}
				for _, inf := range g {
					sb.WriteString("\t")
					sb.WriteString(specLine(inf, false))
					sb.WriteString("\n")
				}
			}
			sb.WriteString(")")
			block = sb.String()
		}

		// Text surgery: replace the first collected declaration with the
		// built block, drop other collected declarations, keep single
		// "C" declarations in place.
		tokFile := fset.File(parsedFile.Pos())
		offset := func(p token.Pos) int {
			if tokFile == nil {
				return 0
			}
			return tokFile.Offset(p)
		}
		var buf bytes.Buffer
		buf.Write(content[:offset(firstCollected.Pos())])
		buf.WriteString(block)
		cursor := offset(firstCollected.End())
		passedFirst := false
		for _, decl := range parsedFile.Decls {
			gd, ok := decl.(*ast.GenDecl)
			if !ok || gd.Tok != token.IMPORT {
				continue
			}
			if gd == firstCollected {
				passedFirst = true
				continue
			}
			if !passedFirst {
				continue
			}
			if len(gd.Specs) == 1 {
				if sp, ok := gd.Specs[0].(*ast.ImportSpec); ok && strings.Trim(sp.Path.Value, "\"") == "C" {
					buf.Write(content[cursor:offset(gd.End())])
					cursor = offset(gd.End())
					continue
				}
			}
			cursor = offset(gd.End())
		}
		buf.Write(content[cursor:])
		newContent = buf.Bytes()
	}

	formatted, err := format.Source(newContent)
	if err != nil {
		// Fall back to the unformatted content if formatting fails; this
		// should not happen for files that parsed successfully.
		formatted = newContent
	}
	if opts.withFormat {
		formatted = applyDeclSpacing(formatted)
	}
	changed := !bytes.Equal(content, formatted)
	return formatted, changed, nil
}

func declsCountHelper(_ *ast.GenDecl, _ *ast.File) int { return 0 }
func countCollectedDecls(i int) int { return i }

func isGeneratedFile(f *ast.File) bool {
	for _, cg := range f.Comments {
		if cg.Pos() >= f.Package {
			continue
		}
		for _, c := range cg.List {
			text := strings.TrimSuffix(c.Text, "\r")
			if generatedRe.MatchString(text) {
				return true
			}
		}
	}
	return false
}

type importInfo struct {
	spec        *ast.ImportSpec
	path        string // unquoted path
	pathClass   string // path as written between quotes (trimmed of ")
	alias       string
	hasAlias    bool
	commentText string
}

func makeImportInfo(sp *ast.ImportSpec) *importInfo {
	raw := sp.Path.Value
	pathClass := strings.Trim(raw, "\"")
	path := pathClass
	if v, err := strconv.Unquote(raw); err == nil {
		path = v
	}
	inf := &importInfo{spec: sp, path: path, pathClass: pathClass}
	if sp.Name != nil {
		inf.alias = sp.Name.Name
		inf.hasAlias = true
	}
	if sp.Comment != nil {
		var parts []string
		for _, c := range sp.Comment.List {
			parts = append(parts, c.Text)
		}
		inf.commentText = strings.Join(parts, " ")
	}
	return inf
}

func dedupImports(infos []*importInfo) []*importInfo {
	index := make(map[string]int)
	var out []*importInfo
	for _, inf := range infos {
		key := inf.alias + "\x00" + inf.pathClass
		if idx, ok := index[key]; ok {
			out[idx] = inf
			continue
		}
		index[key] = len(out)
		out = append(out, inf)
	}
	return out
}

func specLine(inf *importInfo, dupComment bool) string {
	var sb strings.Builder
	if inf.hasAlias {
		sb.WriteString(inf.alias)
		sb.WriteString(" ")
	}
	sb.WriteString(strconv.Quote(inf.path))
	if inf.commentText != "" {
		sb.WriteString(" ")
		sb.WriteString(inf.commentText)
		if dupComment {
			if strings.HasPrefix(inf.commentText, "//") {
				sb.WriteString("\t")
			} else {
				sb.WriteString(" ")
			}
			sb.WriteString(inf.commentText)
		}
	}
	return sb.String()
}

func classify(inf *importInfo, opts *options) groupType {
	if inf.alias == "_" && opts.importsOrderSet[groupBlanked] {
		return groupBlanked
	}
	if inf.alias == "." && opts.importsOrderSet[groupDotted] {
		return groupDotted
	}
	if stdPackages[inf.pathClass] {
		return groupStd
	}
	if opts.projectName != "" {
		if inf.pathClass == opts.projectName || strings.HasPrefix(inf.pathClass, opts.projectName+"/") {
			return groupProject
		}
	}
	for _, prefix := range opts.companyPrefixes {
		if strings.HasPrefix(inf.pathClass, prefix) {
			return groupCompany
		}
	}
	return groupGeneral
}

func buildGroups(infos []*importInfo, opts *options) [][]*importInfo {
	var groups [][]*importInfo
	for _, g := range opts.importsOrder {
		var inGroup []*importInfo
		for _, inf := range infos {
			if classify(inf, opts) == g {
				inGroup = append(inGroup, inf)
			}
		}
		sortImports(inGroup)
		if opts.separateNamed {
			var unnamed, named []*importInfo
			for _, inf := range inGroup {
				if inf.hasAlias {
					named = append(named, inf)
				} else {
					unnamed = append(unnamed, inf)
				}
			}
			if len(unnamed) > 0 {
				groups = append(groups, unnamed)
			}
			if len(named) > 0 {
				groups = append(groups, named)
			}
		} else {
			if len(inGroup) > 0 {
				groups = append(groups, inGroup)
			}
		}
	}
	return groups
}

func sortImports(infos []*importInfo) {
	sort.SliceStable(infos, func(i, j int) bool {
		if infos[i].pathClass != infos[j].pathClass {
			return infos[i].pathClass < infos[j].pathClass
		}
		return infos[i].alias < infos[j].alias
	})
}

// ---------- extra formatting (-format) ----------

func applyDeclSpacing(content []byte) []byte {
	fset := token.NewFileSet()
	parsedFile, err := parser.ParseFile(fset, "", content, parser.ParseComments)
	if err != nil {
		return content
	}
	if len(parsedFile.Decls) < 2 {
		return content
	}
	tokFile := fset.File(parsedFile.Pos())
	lineOf := func(p token.Pos) int {
		if tokFile == nil {
			return 0
		}
		return tokFile.Line(p)
	}
	// Lines that contain a trailing comment for a declaration end.
	trailingCommentLines := make(map[int]bool)
	for _, cg := range parsedFile.Comments {
		for _, c := range cg.List {
			_ = c
		}
		_ = cg
	}
	// Insertions are 0-based line indexes before which a blank line is added.
	var insertBefore []int
	lines := strings.Split(string(content), "\n")
	_ = lines
	for i := 1; i < len(parsedFile.Decls); i++ {
		prev := parsedFile.Decls[i-1]
		cur := parsedFile.Decls[i]
		startLine := lineOf(cur.Pos())
		if doc := docOf(cur); doc != nil {
			startLine = lineOf(doc.Pos())
		}
		prevEndLine := lineOf(prev.End())
		if startLine != prevEndLine+1 {
			continue
		}
		// Skip when the previous declaration ends with a trailing comment.
		if hasCommentOnLine(parsedFile, fset, prevEndLine, prev.End()) {
			_ = trailingCommentLines
			continue
		}
		insertBefore = append(insertBefore, startLine-1) // 0-based index
	}
	if len(insertBefore) == 0 {
		return content
	}
	textLines := strings.Split(string(content), "\n")
	// Insert from last to first.
	sort.Sort(sort.Reverse(sort.IntSlice(insertBefore)))
	for _, idx := range insertBefore {
		if idx < 0 || idx > len(textLines) {
			continue
		}
		textLines = append(textLines, "")
		copy(textLines[idx+1:], textLines[idx:])
		textLines[idx] = ""
	}
	return []byte(strings.Join(textLines, "\n"))
}

func docOf(decl ast.Decl) *ast.CommentGroup {
	switch d := decl.(type) {
	case *ast.FuncDecl:
		return d.Doc
	case *ast.GenDecl:
		return d.Doc
	default:
		return nil
	}
}

func hasCommentOnLine(f *ast.File, fset *token.FileSet, line int, after token.Pos) bool {
	tokFile := fset.File(f.Pos())
	if tokFile == nil {
		return false
	}
	for _, cg := range f.Comments {
		for _, c := range cg.List {
			if c.Pos() >= after && tokFile.Line(c.Pos()) == line {
				return true
			}
		}
	}
	return false
}

// ---------- package loading (rm-unused / set-alias) ----------

type goListError struct {
	Pos string
	Err string
}

type goListPackage struct {
	ImportPath string
	Name       string
	Error      *goListError
	DepsErrors []*goListError
}

func loadPackageInfo(dir string, displayName string, fset *token.FileSet, parsedFile *ast.File) (map[string]string, map[string]bool, error) {
	// 1. Load the containing package (including tests) to mirror the
	// behaviour/error reporting for unresolved imports.
	cmd := exec.Command("go", "list", "-e", "-json", "-test=true", "-compiled=true", "-export=false", "-deps=false", "-find=false", "--", ".")
	cmd.Dir = dir
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return nil, nil, fmt.Errorf("err: %v: stderr: %s", err, stderr.String())
	}
	var errs []*goListError
	seenErr := make(map[string]bool)
	decoder := json.NewDecoder(&stdout)
	for decoder.More() {
		var pkg goListPackage
		if err := decoder.Decode(&pkg); err != nil {
			break
		}
		addErr := func(e *goListError) {
			if e == nil {
				return
			}
			key := e.Pos + "\x00" + e.Err
			if seenErr[key] {
				return
			}
			seenErr[key] = true
			errs = append(errs, e)
		}
		addErr(pkg.Error)
		for _, e := range pkg.DepsErrors {
			addErr(e)
		}
	}
	if len(errs) > 0 {
		for _, e := range errs {
			if e.Pos != "" {
				fmt.Fprintf(os.Stderr, "%s: %s\n", e.Pos, e.Err)
			} else {
				fmt.Fprintln(os.Stderr, e.Err)
			}
		}
		return nil, nil, errors.New("package has an errors")
	}

	// 2. Resolve names of the imports used by this file.
	names := make(map[string]string)
	var importPaths []string
	seenPath := make(map[string]bool)
	for _, imp := range parsedFile.Imports {
		p, err := strconv.Unquote(imp.Path.Value)
		if err != nil {
			p = strings.Trim(imp.Path.Value, "\"")
		}
		if p == "C" || seenPath[p] {
			continue
		}
		seenPath[p] = true
		importPaths = append(importPaths, p)
	}
	if len(importPaths) > 0 {
		args := []string{"list", "-e", "-json", "--"}
		args = append(args, importPaths...)
		cmd2 := exec.Command("go", args...)
		cmd2.Dir = dir
		var out2, err2 bytes.Buffer
		cmd2.Stdout = &out2
		cmd2.Stderr = &err2
		if err := cmd2.Run(); err != nil {
			return nil, nil, fmt.Errorf("err: %v: stderr: %s", err, err2.String())
		}
		dec2 := json.NewDecoder(&out2)
		var loadErrs []string
		for dec2.More() {
			var pkg goListPackage
			// Reuse struct but it has Error field.
			var raw struct {
				ImportPath string
				Name       string
				Error      *goListError
			}
			if err := dec2.Decode(&raw); err != nil {
				break
			}
			_ = pkg
			if raw.Name != "" {
				names[raw.ImportPath] = raw.Name
			} else if raw.Error != nil {
				// Locate the import spec for the position.
				posStr := baseName(displayName) + ":1:1"
				for _, imp := range parsedFile.Imports {
					p, _ := strconv.Unquote(imp.Path.Value)
					if p == raw.ImportPath {
						if tokFile := fset.File(parsedFile.Pos()); tokFile != nil {
							pos := tokFile.Position(imp.Pos())
							posStr = fmt.Sprintf("%s:%d:1", baseName(displayName), pos.Line)
						}
					}
				}
				msg := raw.Error.Err
				loadErrs = append(loadErrs, fmt.Sprintf("%s: %s", posStr, msg))
			}
		}
		if len(loadErrs) > 0 {
			for _, m := range loadErrs {
				fmt.Fprintln(os.Stderr, m)
			}
			return nil, nil, errors.New("package has an errors")
		}
	}

	used := computeUsedImports(fset, parsedFile, names)
	return names, used, nil
}

func baseName(p string) string {
	if p == "<standard-input>" {
		return p
	}
	return filepath.Base(p)
}

// computeUsedImports type-checks the (single) parsed file with stub imported
// packages and records which imported packages are actually referenced.
func computeUsedImports(fset *token.FileSet, parsedFile *ast.File, names map[string]string) (used map[string]bool) {
	used = make(map[string]bool)
	defer func() {
		if r := recover(); r != nil {
			// Fall back to a selector scan on panic.
			used = fallbackUsedImports(parsedFile, names)
		}
	}()
	imp := &stubImporter{packages: make(map[string]*types.Package), names: names}
	conf := types.Config{
		Importer:                 imp,
		FakeImportC:              true,
		DisableUnusedImportCheck: true,
		Error:                    func(err error) {},
	}
	info := &types.Info{
		Uses: make(map[*ast.Ident]types.Object),
	}
	_, _ = conf.Check(parsedFile.Name.Name, fset, []*ast.File{parsedFile}, info)
	for _, obj := range info.Uses {
		if pkgName, ok := obj.(*types.PkgName); ok {
			used[pkgName.Imported().Path()] = true
		}
	}
	return used
}

func fallbackUsedImports(parsedFile *ast.File, names map[string]string) map[string]bool {
	// Map effective identifier name -> import path.
	byName := make(map[string]string)
	for _, imp := range parsedFile.Imports {
		p, err := strconv.Unquote(imp.Path.Value)
		if err != nil {
			p = strings.Trim(imp.Path.Value, "\"")
		}
		var name string
		if imp.Name != nil {
			name = imp.Name.Name
			if name == "_" || name == "." {
				continue
			}
		} else if n, ok := names[p]; ok {
			name = n
		} else {
			name = p
			if idx := strings.LastIndex(name, "/"); idx >= 0 {
				name = name[idx+1:]
			}
		}
		byName[name] = p
	}
	used := make(map[string]bool)
	ast.Inspect(parsedFile, func(n ast.Node) bool {
		if sel, ok := n.(*ast.SelectorExpr); ok {
			if id, ok := sel.X.(*ast.Ident); ok {
				if p, ok := byName[id.Name]; ok {
					used[p] = true
				}
			}
		}
		return true
	})
	return used
}

type stubImporter struct {
	packages map[string]*types.Package
	names    map[string]string
}

func (s *stubImporter) Import(path string) (*types.Package, error) {
	if pkg, ok := s.packages[path]; ok {
		return pkg, nil
	}
	name, ok := s.names[path]
	if !ok || name == "" {
		name = path
		if idx := strings.LastIndex(name, "/"); idx >= 0 {
			name = name[idx+1:]
		}
		// Strip a trailing version suffix such as v2 for a best effort name.
		if len(name) > 1 && name[0] == 'v' {
			isVer := true
			for _, ch := range name[1:] {
				if ch < '0' || ch > '9' {
					isVer = false
					break
				}
			}
			if isVer {
				// Keep "vN" fallback; usage detection uses paths anyway.
			}
		}
	}
	pkg := types.NewPackage(path, name)
	pkg.MarkComplete()
	s.packages[path] = pkg
	return pkg, nil
}
GO"}

