func goListNames(dir string, importPaths []string) (map[string]string, error) {
	m, _, err := goListNamesWithErrors(dir, importPaths, "", nil, nil)
	return m, err
}

func goListNamesWithErrors(dir string, importPaths []string, displayName string, fset *token.FileSet, parsedFile *ast.File) (map[string]string, []string, error) {
	names := make(map[string]string)
	args := []string{"list", "-e", "-json", "--"}
	args = append(args, importPaths...)
	cmd2 := exec.Command("go", args...)
	cmd2.Dir = dir
	var out2, err2 bytes.Buffer
	cmd2.Stdout = &out2
	cmd2.Stderr = &err2
	if err := cmd2.Run(); err != nil {
		return nil, nil, fmt.Errorf("err: %v: stderr: %s\\n", err, err2.String())
	}
	dec2 := json.NewDecoder(&out2)
	var loadErrs []string
	for dec2.More() {
		var raw struct {
			ImportPath string
			Name       string
			Error      *goListError
		}
		if err := dec2.Decode(&raw); err != nil {
			break
		}
		if raw.Name != "" {
			names[raw.ImportPath] = raw.Name
		} else if raw.Error != nil && displayName != "" && fset != nil && parsedFile != nil {
			posStr := baseName(displayName) + ":1:1"
			for _, imp := range parsedFile.Imports {
				p, _ := strconv.Unquote(imp.Path.Value)
				if p == raw.ImportPath {
					if tokFile := fset.File(parsedFile.Pos()); tokFile != nil {
						pos := tokFile.Position(imp.Pos())
						posStr = fmt.Sprintf("%s:%d:1", baseName(displayName), pos.Line)
					}
				}
			}
			loadErrs = append(loadErrs, fmt.Sprintf("%s: %s", posStr, raw.Error.Err))
		}
	}
	return names, loadErrs, nil
}

